class ParentCtor {
    ParentCtor(){ System.out.println(label()); }
    String label(){ return "parent"; }
}
class ChildCtor extends ParentCtor {
    private String name = "ready";
    @Override String label(){ return name; }
}
public class ConstructorDispatchRiskDemo {
    public static void main(String[] args){ new ChildCtor(); }
}
